        "alternative_ids": ["A4", "A5"]
      },
      {
        "id": "T3",
        "description": "Declining to ship the AI assistant this quarter sets the recommendation against the VP's stated preference.",
        "gains": ["Avoids an unpriced vendor commitment and a six-to-eight week assessment with no defined use case"],
        "gives_up": ["Executive sponsor satisfaction; the perceived competitive-parity argument"],
        "alternative_ids": ["A3"]
      }
    ],
    "experiment": {
      "id": "EXP1",
      "hypothesis": "For apartment-type deliveries, validating the address on the order path and ensuring the unit number reaches the label and carrier manifest raises first-attempt delivery success by at least 2 percentage points over the 84.1% baseline and reduces address_error support tickets per 1,000 apartment deliveries, without raising cost per delivery.",
      "method": "Randomised assignment of apartment-type orders (not zones, to avoid the post-hoc comparison-group error of the 2024 notification pilot) to treatment or holdout in two metros. Treatment: order-path address validation plus mandatory unit-number confirmation at checkout, with the confirmed unit propagated to label and manifest. Holdout: current behaviour. Pre-register the primary metric and the analysis window. Read out weekly on a next-day data cadence given the up-to-24-hour warehouse lag. Report house-segment orders separately and do not generalise the result to them.",
      "duration": "8 weeks of exposure plus 1 week for exception events to settle, given the up-to-24-hour warehouse lag",
      "metrics": [
        {"name": "Apartment first-attempt delivery success", "role": "success", "definition": "Share of apartment-segment deliveries succeeding on first attempt, treatment vs randomised holdout", "target": "+2pp or more over the 84.1% 2026-Q2 apartment baseline, statistically distinguishable from holdout", "rationale": "The primary outcome the FY26 goal is written against, measured on the segment the evidence actually supports."},
        {"name": "Address_error support tickets per 1,000 apartment deliveries", "role": "success", "definition": "Tickets categorised address_error, normalised by apartment delivery volume", "target": "Material reduction vs holdout over the 8-week window", "rationale": "Address_error is 37.3% of apartment tickets (921 in 2026-Q2); if the mechanism works this category must move."},
        {"name": "Unit-number capture completeness", "role": "success", "definition": "Share of apartment orders leaving checkout with a validated unit number present on the manifest", "target": "Near-complete capture in treatment", "rationale": "Distinguishes a capture failure from a propagation failure — CF-002 reports entering the unit at checkout and it still not appearing."},
        {"name": "Cost per delivery index", "role": "guardrail", "definition": "The existing cost_per_delivery_index, treatment cohort vs holdout", "target": "No increase above the 2026-Q2 value of 100.0", "rationale": "Cost per delivery is the binding FY26 constraint; a per-delivery cost rise requires finance approval."},
        {"name": "Checkout completion rate", "role": "guardrail", "definition": "Share of apartment-segment carts completing checkout", "target": "No statistically detectable decline vs holdout", "rationale": "Adding a mandatory field is the most likely way this intervention causes commercial harm."},
        {"name": "Address validation request rate", "role": "guardrail", "definition": "Peak requests per second against the vendor cap", "target": "Sustained peak below 50 requests per second", "rationale": "The contract imposes a hard cap of 50 requests per second; breaching it degrades the order path."},
        {"name": "Total support contacts per 1,000 deliveries", "role": "guardrail", "definition": "All delivery-related contacts, treatment vs holdout", "target": "No increase above the 2026-Q2 level of 38.2", "rationale": "Guards against shifting exceptions into another category rather than eliminating them."},
        {"name": "Misdelivery complaints", "role": "guardrail", "definition": "Tickets describing delivery to the wrong unit or building", "target": "No increase vs holdout", "rationale": "An incorrect auto-validated unit number could route packages to the wrong door; CF-004 shows this failure mode already exists."}
      ]
